// Types for proximity incentive system
interface ProximityIncentive {
  id: string;
  taskId: string;
  nodeId: string;
  distance: number;
  tier: string;
  multiplier: number;
  baseReward: number;
  totalReward: number;
  calculatedAt: Date;
  coordinates: {
    taskLat: number;
    taskLon: number;
    nodeLat: number;
    nodeLon: number;
  };
}

// Distance tiers configuration
const DISTANCE_TIERS = {
  SAME_REGION: { min: 0, max: 50, multiplier: 2.0 },
  NEAR_REGION: { min: 50, max: 200, multiplier: 1.5 },
  FAR_REGION: { min: 200, max: 1000, multiplier: 1.2 },
  VERY_FAR: { min: 1000, max: Infinity, multiplier: 1.0 },
};

// Haversine formula for distance calculation
function calculateDistance(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const R = 6371; // Earth's radius in kilometers
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  const distance = R * c;
  return distance;
}

// Get distance tier based on distance
function getDistanceTier(distance: number): string {
  if (distance <= DISTANCE_TIERS.SAME_REGION.max) return 'SAME_REGION';
  if (distance <= DISTANCE_TIERS.NEAR_REGION.max) return 'NEAR_REGION';
  if (distance <= DISTANCE_TIERS.FAR_REGION.max) return 'FAR_REGION';
  return 'VERY_FAR';
}

// Get base multiplier for tier
function getBaseMultiplier(tier: string): number {
  return DISTANCE_TIERS[tier as keyof typeof DISTANCE_TIERS]?.multiplier || 1.0;
}

// Calculate proximity incentive
function calculateIncentive(task: any, node: any): ProximityIncentive {
  const distance = calculateDistance(
    parseFloat(task.latitude),
    parseFloat(task.longitude),
    parseFloat(node.latitude),
    parseFloat(node.longitude)
  );

  const tier = getDistanceTier(distance);
  const multiplier = getBaseMultiplier(tier);
  const baseReward = task.baseReward || 1.0;
  const totalReward = baseReward * multiplier;

  return {
    id: `incentive-${task.id}-${node.id}-${Date.now()}`,
    taskId: task.id.toString(),
    nodeId: node.id.toString(),
    distance,
    tier,
    multiplier,
    baseReward,
    totalReward,
    calculatedAt: new Date(),
    coordinates: {
      taskLat: parseFloat(task.latitude),
      taskLon: parseFloat(task.longitude),
      nodeLat: parseFloat(node.latitude),
      nodeLon: parseFloat(node.longitude),
    },
  };
}

// Find optimal node for task
function findOptimalNode(
  task: any
): { optimalNode: any; incentive: ProximityIncentive } | null {
  // This is a simplified implementation
  // In a real system, you'd query all available nodes and find the best match
  const mockNode = {
    id: 1,
    nodeId: 'optimal-node-1',
    latitude: task.latitude,
    longitude: task.longitude,
    capabilities: {},
    status: 'active',
  };

  const incentive = calculateIncentive(task, mockNode);
  return { optimalNode: mockNode, incentive };
}

// Store incentive (mock implementation)
function storeIncentive(incentive: ProximityIncentive): ProximityIncentive {
  // In a real implementation, this would store to database
  return incentive;
}

