/**
 * @api {post} /api/proximity/calculate Calculate proximity incentive
 * @apiName CalculateProximityIncentive
 * @apiGroup Proximity
 * @apiDescription Calculate the proximity incentive for a task-node pair
 *
 * @apiParam {Object} req.body.task Task information (id, taskId, latitude, longitude, regionCode, taskType, priority, baseReward)
 * @apiParam {Object} req.body.node Node information (id, nodeId, latitude, longitude, regionCode, capabilities)
 *
 * @apiSuccess {Object} incentive Calculated proximity incentive
 */
router.post('/calculate', async (req: Request, res: Response) => {
  try {
    const { task, node } = req.body;

    if (!task || !node) {
      res
        .status(400)
        .json(
          createErrorResponse(
            'Missing task or node data',
            'VALIDATION_ERROR'
          )
        );
      return;
    }

    if (
      !task.latitude ||
      !task.longitude ||
      !node.latitude ||
      !node.longitude
    ) {
      res
        .status(400)
        .json(
          createErrorResponse(
            'Geographic coordinates are required',
            'VALIDATION_ERROR'
          )
        );
      return;
    }

    // Use our local implementation instead of the missing controller method
    const incentive = calculateIncentive(task, node);

    res.json({ success: true, incentive });
  } catch (error) {
    computeLogger.error('Error calculating proximity incentive', { error: error instanceof Error ? error.message : 'Unknown error', stack: error instanceof Error ? error.stack : undefined });
    res
      .status(500)
      .json(
        createErrorResponse(
          'Failed to calculate proximity incentive',
          'PROXIMITY_ERROR'
        )
      );
  }
});

/**
 * @api {post} /api/proximity/tasks/:taskId/optimal-node Find optimal node for task
 * @apiName FindOptimalNodeForTask
 * @apiGroup Proximity
 * @apiDescription Find the optimal node for a computational task based on proximity incentives
 *
 * @apiParam {String} taskId Task ID
 * @apiSuccess {Object} result Object containing task, optimal node, and incentive details
 */
router.post(
  '/tasks/:taskId/optimal-node',
  async (req: Request, res: Response) => {
    try {
      const { taskId } = req.params;
      const task = await storage.getComputationalTaskById(parseInt(taskId, 10));

      if (!task) {
        res.status(404).json(createErrorResponse('Task not found', 'NOT_FOUND'));
        return;
      }

      // Use our local implementation instead of the missing controller method
      const result = findOptimalNode(task);

      if (!result) {
        res
          .status(404)
          .json(createErrorResponse('No optimal node found', 'NOT_FOUND'));
        return;
      }

      // Store the incentive calculation using our local implementation
      const storedIncentive = storeIncentive(result.incentive);

      // Update the task with the assigned node
      await storage.updateComputationalTask(task.taskId, {
        assignedNodeId: result.optimalNode.id.toString(),
        status: 'ASSIGNED',
      });

      res.json({
        success: true,
        task,
        optimalNode: result.optimalNode,
        incentive: storedIncentive,
      });
    } catch (error) {
    computeLogger.error('Error finding optimal node for task', { taskId: req.params.taskId, error: error instanceof Error ? error.message : 'Unknown error', stack: error instanceof Error ? error.stack : undefined });
    res
      .status(500)
      .json(
        createErrorResponse(
          'Failed to find optimal node for task',
          'PROXIMITY_ERROR'
        )
      );
    }
  }
);

