/**
 * @api {post} /api/proximity/distance Calculate distance
 * @apiName CalculateDistance
 * @apiGroup Proximity
 * @apiDescription Calculate the distance between two geographic points
 *
 * @apiParam {Number} req.body.lat1 Latitude of first point
 * @apiParam {Number} req.body.lon1 Longitude of first point
 * @apiParam {Number} req.body.lat2 Latitude of second point
 * @apiParam {Number} req.body.lon2 Longitude of second point
 *
 * @apiSuccess {Number} distance Distance in kilometers
 * @apiSuccess {String} tier Distance tier
 * @apiSuccess {Number} multiplier Base multiplier for the tier
 */
router.post('/distance', (req: Request, res: Response): void => {
  try {
    const { lat1, lon1, lat2, lon2 } = req.body;

    if (!lat1 || !lon1 || !lat2 || !lon2) {
      res
        .status(400)
        .json(createErrorResponse('Missing coordinates', 'VALIDATION_ERROR'));
      return;
    }

    // Use our local implementations instead of the missing controller methods
    const distance = calculateDistance(lat1, lon1, lat2, lon2);
    const tier = getDistanceTier(distance);
    const multiplier = getBaseMultiplier(tier);

    res.json({
      success: true,
      distance,
      tier,
      multiplier,
    });
  } catch (error) {
    computeLogger.error('Error calculating distance', { error: error instanceof Error ? error.message : 'Unknown error', stack: error instanceof Error ? error.stack : undefined });
    res
      .status(500)
      .json(
        createErrorResponse('Failed to calculate distance', 'PROXIMITY_ERROR')
      );
  }
});

export default router;
